local function begin(i, tap, action)
    if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
        pressed, moved, onTap, dragStart, startPos = true, false, tap, i.Position, frame.Position
        onAction = action
        pressId = pressId + 1
        local myId = pressId
        if not tap then
            task.delay(1.6, function()
                if pressed and pressId == myId and not moved and not closed then askDelete() end
            end)
        end
    end
end
